package shape

import (
	"github.com/KogenAI/kogen-executor/agent"
	"github.com/KogenAI/kogen-loop/tools"
)

// scopeCeiling is the review ceiling: the review stage's own setting.
func scopeCeiling() int { return tools.InputBudgetBytes }

// scopeOver reports whether an estimate is over the inclusive ceiling.
func scopeOver(bytes, ceiling int) bool { return bytes > ceiling }

// scopeReviewInputs are the fixed review inputs every review carries: the README at HEAD and the
// testing rules.
func scopeReviewInputs(head map[string]int) []scopeFile {
	return []scopeFile{{scopeReadme, head[scopeReadme]}, {scopeRules, len(agent.Prompt(agent.TestingRules))}}
}

// estimate is the bytes of mandatory review material of the Intent as one review.
func (in scopeInput) estimate() int {
	return scopeSum(in.pkg, in.inputs, in.changedFiles(in.intentText))
}

// partEstimate is the same for a part, whose own package does not exist yet.
func (in scopeInput) partEstimate(p scopePart) int {
	return scopeSum(in.inputs, in.changedFiles(p.text))
}

// scopeExempt reports whether the Intent text is exempt from the check; none is.
func scopeExempt(text string) bool { return false }

// scopeCheckedParts are the parts of a split whose estimate is checked: every one.
func scopeCheckedParts(parts []scopePart) []scopePart { return parts }

// scopeAnnounces reports whether a split is announced to the user.
func scopeAnnounces(parts []scopePart) bool { return len(parts) > 0 }

